<div class="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4"><div><h1 class="h3 mb-1">Planos de treino</h1><p class="text-secondary mb-0">Organize ciclos e distribua treinos pela semana.</p></div><div class="d-flex gap-2"><a class="btn btn-outline-secondary" href="<?= escapar(url('/treinos')) ?>">Treinos</a><a class="btn btn-success" href="<?= escapar(url('/treinos/planos/formulario')) ?>"><i class="bi bi-plus-lg me-1"></i>Novo plano</a></div></div>
<div class="card"><?php if (!$planos): ?><div class="card-body p-5 text-center"><i class="bi bi-calendar2-week display-5 text-success"></i><h2 class="h5 mt-3">Nenhum plano cadastrado</h2><p class="text-secondary">Crie um plano para começar a organizar seus treinos.</p></div><?php else: ?><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead class="table-light"><tr><th>Plano</th><th>Vigência</th><th>Estrutura</th><th>Situação</th><th class="tabela-acoes"></th></tr></thead><tbody><?php foreach ($planos as $plano): ?><?php $situacao = situacao_plano_treino($plano); ?><tr><td><span class="fw-semibold"><?= escapar($plano['ptr_nome']) ?></span><br><span class="small text-secondary"><?= escapar($plano['ptr_objetivo'] ?: '') ?></span></td><td><?= escapar(formatar_data($plano['ptr_data_inicio'])) ?><?= $plano['ptr_data_fim'] ? ' a ' . escapar(formatar_data($plano['ptr_data_fim'])) : ' em diante' ?></td><td><?= (int) $plano['total_treinos'] ?> treino(s) · <?= (int) $plano['total_exercicios'] ?> exercício(s)</td><td><span class="badge <?= escapar($situacao['classe']) ?>"><?= escapar($situacao['rotulo']) ?></span></td><td><a class="btn btn-sm btn-outline-success btn-icone" href="<?= escapar(url('/treinos/planos/detalhes?id=' . $plano['ptr_id'])) ?>"><i class="bi bi-eye"></i></a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
